class DiscriminantAnalysisPredictionMixin(_StubEstimator):
    """Stub for sklearn's :class:`DiscriminantAnalysisPredictionMixin`. The shim doesn't implement
    the algorithm; methods record their arguments and return self/None."""
    pass


