def check_classification_targets(y): return None
def check_is_fitted(*a, **kw): return None
def device(*a, **kw): return None
def empirical_covariance(X, *a, **kw):
    import numpy as _np
    X = _np.asarray(X)
    return _np.cov(X.T) if X.ndim == 2 else _np.array([[1.0]])
def get_namespace(*a, **kw):
    import numpy as _np
    return _np, False
def ledoit_wolf(X, *a, **kw):
    import numpy as _np
    X = _np.asarray(X)
    return _np.cov(X.T), 0.5
def shrunk_covariance(emp_cov, *a, **kw): return emp_cov
def size(x, *a, **kw):
    try: return getattr(x, "size", len(x))
    except Exception: return 0
def softmax(x, **kw):
    try:
        import numpy as _np
        x = _np.asarray(x)
        e = _np.exp(x - _np.max(x, axis=-1, keepdims=True))
        return e / e.sum(axis=-1, keepdims=True)
    except Exception:
        return x
def unique_labels(*ys):
    seen = []
    for y in ys:
        for v in (y or ()):
            if v not in seen: seen.append(v)
    return seen
def validate_data(*a, **kw):
    if a: return a[0]
    return None
